1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x1, y1]: Cell, [x2, y2]: Cell): boolean => x1 === x2 && y1 === y2;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const containsCell = (cells: Cell[], cell: Cell): boolean =>
17	  cells.some((other) => isSameCell(other, cell));
18	
19	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
20	  neighborsOf(cell).filter((neighbor) => containsCell(liveCells, neighbor)).length;
21	
22	const isAliveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
23	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
24	  return liveNeighbors === 3 || (liveNeighbors === 2 && containsCell(liveCells, cell));
25	};
26	
27	const distinctCells = (cells: Cell[]): Cell[] =>
28	  cells.filter((cell, index) => !containsCell(cells.slice(0, index), cell));
29	
30	const candidateCells = (liveCells: Cell[]): Cell[] =>
31	  distinctCells([...liveCells, ...liveCells.flatMap(neighborsOf)]);
32	
33	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
34	  candidateCells(liveCells).filter((cell) => isAliveNextGeneration(cell, liveCells));
